import { formatEuros } from './money.js';
import { getCustomer } from './customers.js';
import { lineTotal, invoiceTotals } from './invoices.js';
import { balanceDue } from './payments.js';

/**
 * Render an invoice as plain text for display to customers.
 * @param {{ number?: string, customerId: string, issueDate: string, status: string, lines: Array, dueDate?: string, voucher?: { code: string, amount: number }, payments?: Array }}
 * @returns {string} Plain-text invoice
 */
export function renderInvoiceText(invoice) {
  const lines = [];

  // Invoice number or DRAFT
  lines.push(invoice.number || 'DRAFT');

  // Customer name
  const customerResult = getCustomer(invoice.customerId);
  const customerName = customerResult.ok ? customerResult.value.name : 'Unknown Customer';
  lines.push(customerName);

  // Line items with discounts
  for (const line of invoice.lines) {
    const total = lineTotal(line);
    let lineText = `${line.qty} x ${line.name} at ${formatEuros(line.unitPrice)} = ${formatEuros(total)}`;

    // Add discount if present
    if (line.discountPercent && line.discountPercent > 0) {
      const discount = Math.round((total * line.discountPercent) / 100);
      lineText += ` (discount: ${formatEuros(discount)})`;
    }

    lines.push(lineText);
  }

  // VAT and Total
  const totals = invoiceTotals(invoice);
  if (totals.vat > 0) {
    lines.push(`VAT: ${formatEuros(totals.vat)}`);
  }

  // Voucher if present
  if (totals.voucher > 0) {
    lines.push(`Voucher: ${formatEuros(totals.voucher)}`);
  }

  lines.push(`Total: ${formatEuros(totals.total)}`);

  // Due date if present
  if (invoice.dueDate) {
    lines.push(`Due: ${invoice.dueDate}`);
  }

  // Paid amount if there are payments
  if (invoice.payments && invoice.payments.length > 0) {
    const totalPaid = invoice.payments.reduce((sum, p) => sum + p.amount, 0);
    lines.push(`Paid: ${formatEuros(totalPaid)}`);
  }

  return lines.join('\n');
}

