test('renderInvoiceText shows line discount', () => {
  const invoice = createInvoice({
    customerId: 'C-002', // standard tier = 0% discount
    issueDate: '2025-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 2, discountPercent: 10 }],
  }).value;

  const text = renderInvoiceText(invoice);
