test('renderInvoiceText shows voucher before total', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-15',
    lines: [{ sku: 'STICKER', qty: 5 }],
  }).value;

  const withVoucher = applyVoucher(invoice, { code: 'PROMO', amount: 100 }).value;
  const text = renderInvoiceText(withVoucher);
  const lines = text.split('\n');

  // Should have voucher line before total
  const totalIndex = lines.findIndex((l) => l.startsWith('Total:'));
  const voucherIndex = lines.findIndex((l) => l.startsWith('Voucher:'));
  assert.ok(voucherIndex > 0);
  assert.ok(voucherIndex < totalIndex);
  assert.equal(lines[voucherIndex], 'Voucher: €1.00');
});

test('renderInvoiceText shows due date when present', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2025-10-01',
    lines: [{ sku: 'STICKER', qty: 100 }],
    terms: 'NET14',
  }).value;

  const text = renderInvoiceText(invoice);
  const lines = text.split('\n');

  assert.ok(lines[lines.length - 1].startsWith('Due:'));
  assert.equal(lines[lines.length - 1], 'Due: 2025-10-15');
});

